Object.assign(window.TEM8_DICTIONARY, {"garage":{"media":{"uk":"media/uk/garage__gb_1.mp3","us":"media/us/garage__us_1.mp3","img":["media/ldoce/img/garage.jpg"]},"oxford":{"phon":"ˈɡærɑːʒ","pos":"noun","senses":[{"en":"a building for keeping one or more cars or other vehicles in","cn":"停车房；车库","g":"[countable]","ex":{"en":"a double garage (= one for two cars)","cn":"双车位车库"}},{"en":"a place where vehicles are repaired and/or where you can buy a car or buy petrol and oil","cn":"（兼营汽车销售、修理及加油的）汽车修理厂","g":"[countable]","ex":{"en":"I had to take the car to the garage.","cn":"我不得不把车开到维修站去。"}},{"en":"a style of rock music played with great energy but not necessarily great technique, popular in the 1960s","cn":"车库摇滚乐（流行于 20 世纪 60 年代）","g":"[uncountable]"},{"en":"a type of electronic dance music with elements of drum and bass, house music and soul","cn":"英式车库（一种电子舞曲，融合鼓打贝司、浩室音乐和灵乐元素）","g":"[uncountable]"},{"en":"to put or keep a vehicle in a garage","cn":"把…送入车库（或修车厂）","ex":{"en":"They have space to garage two cars.","cn":"他们有空间停放两辆车。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"车库；停车房","en":"A garage is a building in which you keep a car. A garage is often built next to or as part of a house."},{"pos":"N-COUNT; N-IN-NAMES 名称名词；名称名词","cn":"汽车修理厂（在英国兼营加油或汽车销售）","en":"A garage is a place where you can get your car repaired. In Britain, you can also buy fuel for your car, or buy cars.","ex":{"en":"Nancy took her car to a local garage for a check-up","cn":"南希把车开到当地的汽车修理厂检修。"}}]},"examples":[{"en":"a double garage (= one for two cars)","cn":"停放两辆车的车房"},{"en":"( BrE ) a house with a built-in garage","cn":"内设车库的房子"}]},"gap":{"media":{"uk":"media/uk/gap__gb_1.mp3","us":"media/us/gap__us_1.mp3"},"oxford":{"phon":"ɡæp","pos":"noun","senses":[{"en":"a space where something is missing","cn":"缺口；空白；漏洞","ex":{"en":"Extra funding is needed to plug the gap.","cn":"需要额外资金来填补这一缺口。"}},{"en":"a space between two things or in the middle of something, especially because there is a part missing","cn":"开口；豁口；缺口；裂口","ex":{"en":"There should be a six-inch gap at the bottom.","cn":"底部应该有六英寸的间隙。"}},{"en":"a period of time when something stops, or between two events","cn":"间断；间隔；间隙","ex":{"en":"a gap in the conversation","cn":"谈话的间隙"}},{"en":"a difference that separates people, or their opinions, situation, etc.","cn":"分歧；隔阂；差距","ex":{"en":"A huge gap has opened up between expectations and what is deliverable.","cn":"期望与现实所得之间出现了巨大的反差。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"缝隙；缺口；豁口；裂口","en":"A gap is a space between two things or a hole in the middle of something solid.","ex":{"en":"He pulled the thick curtains together, leaving just a narrow gap.","cn":"他拉上厚厚的窗帘，仅留下一条狭窄的缝隙。"}},{"pos":"N-COUNT 可数名词","cn":"（时间上的）间断，间隔，间隙","en":"A gap is a period of time when you are not busy or when you stop doing something that you normally do.","ex":{"en":"There followed a gap of four years, during which William joined the Army.","cn":"随后的4年时间，威廉在陆军服役。"}},{"pos":"N-COUNT 可数名词","cn":"漏洞；空白；缺口","en":"If there is something missing from a situation that prevents it being complete or satisfactory, you can say that there is a gap .","ex":{"en":"We need more young scientists to fill the gap left by a wave of retirements expected over the next decade","cn":"我们需要更多年轻的科学家来填补预计未来10年退休高峰带来的人才缺口。"}},{"pos":"N-COUNT 可数名词","cn":"分歧；差距；隔阂","en":"A gap between two groups of people, things, or sets of ideas is a big difference between them.","ex":{"en":"...the gap between rich and poor","cn":"贫富差距"}}]},"examples":[{"en":"We think we've identified a gap in the market (= a business opportunity to make or sell sth that is not yet available).","cn":"我们认为已经发现了市场上一个尚待填补的空白。"},{"en":"His death left an enormous gap in my life.","cn":"他去世给我的生活留下巨大的空白。"}]},"gate":{"oxford":{"phon":"ɡeɪt","pos":"noun","senses":[{"en":"a barrier like a door that is used to close an opening in a fence or a wall outside a building","cn":"大门；栅栏门；围墙门","g":"[countable]","ex":{"en":"the front/main gate","cn":"前门；大门"}},{"en":"an opening that can be closed by a gate or gates","cn":"大门口","g":"[countable]","ex":{"en":"I was slightly nervous as I entered the gates.","cn":"当我进入大门时，我有点紧张。"}},{"en":"a way out of an airport through which passengers go to get on their plane","cn":"登机门；登机口","g":"[countable]","ex":{"en":"Passengers for Paris should proceed to gate 8.","cn":"前往巴黎的乘客应前往 8 号登机口。"}},{"en":"a barrier that is used to control the flow of water on a river or canal","cn":"闸门；阀门","g":"[countable]","ex":{"en":"a lock/sluice gate","cn":"船闸闸门；水闸"}},{"en":"the number of people who attend a sports event","cn":"（体育比赛的）观众人数","g":"[countable]","ex":{"en":"Tonight's game has attracted the largest gate of the season.","cn":"今晚比赛吸引的观众人数创本赛季之最。"}},{"en":"the amount of money made by selling tickets for a sports event","cn":"（体育比赛的）门票收入","g":"[uncountable]","ex":{"en":"Today's gate will be given to charity.","cn":"今天的门票收入将捐献给慈善事业。"}},{"en":"a political scandal connected with the person, place or event mentioned, usually involving a cover-up (= an attempt to hide an illegal activity)","cn":"（尤指有人试图掩盖的）丑闻","ex":{"en":"The newspapers have been running stories on the Partygate scandal for months.","cn":"几个月来，报纸一直在报道派对门丑闻。"}},{"en":"an electronic switch that reacts in one of two ways to data that is put into it. A computer performs operations by passing data through a very large number of gates.","cn":"门（电路）","lab":"computing"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"大门；门","en":"A gate is a structure like a door which is used at the entrance to a field, a garden, or the grounds of a building.","ex":{"en":"He opened the gate and started walking up to the house.","cn":"他打开大门，迈步朝房子走去。"}},{"pos":"N-COUNT 可数名词","cn":"登机门；登机口","en":"In an airport, a gate is a place where passengers leave the airport and get on their aeroplane.","ex":{"en":"Passengers with hand luggage can go straight to the departure gate to check in there.","cn":"携带手提行李的乘客可直接到登机口办理登机手续。"}},{"pos":"N-IN-NAMES 名称名词","cn":"…门（在英国用于街道名）","en":"Gate is used in the names of streets in Britain that are in a place where there once was a gate into a city.","ex":{"en":"...9 Palace Gate.","cn":"王宫门9号"}},{"pos":"N-COUNT 可数名词","cn":"（体育比赛的）观众总人数","en":"The gate at a sporting event such as a football match or baseball game is the total number of people who attend it.","ex":{"en":"Their average gate is less than 23,000.","cn":"他们的平均上座率不到23,000人。"}}]},"media":{"uk":"media/uk/gate__gb_1.mp3","us":"media/us/gate__us_1.mp3"},"examples":[{"en":"BA flight 726 to Paris is now boarding at gate 16.","cn":"飞往巴黎的英航 726 号班机在 16 号门登机。"},{"en":"Tonight's game has attracted the largest gate of the season.","cn":"今晚比赛吸引的观众人数创本赛季之最。"}]},"gathering":{"oxford":{"phon":"ˈɡæðərɪŋ","pos":"noun","senses":[{"en":"a meeting of people for a particular purpose","cn":"聚集；聚会；集会","g":"[countable]","ex":{"en":"a social/family gathering","cn":"社交／家庭聚会"}},{"en":"the process of collecting something","cn":"收集；采集；搜集","g":"[uncountable]","ex":{"en":"methods of information gathering","cn":"信息采集的各种方法"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"集会；聚会","en":"A gathering is a group of people meeting together for a particular purpose.","ex":{"en":"...the twenty-second annual gathering of the South Pacific Forum.","cn":"第22届南太平洋论坛年会"}},{"pos":"ADJ 形容词","cn":"（夜色）渐浓的，逐渐变黑的","en":"If there is gathering darkness, the light is gradually decreasing, usually because it is nearly night.","ex":{"en":"The lighthouse beam was quite distinct in the gathering dusk.","cn":"灯塔的光束在渐浓的暮色中清晰可见。"}}]},"media":{"uk":"media/uk/gathering__gb_1.mp3","us":"media/us/gathering__us_1.mp3"},"examples":[{"en":"methods of information gathering","cn":"信息采集的各种方法"},{"en":"a social/family gathering","cn":"社交/家庭聚会"}],"base":"gather"},"gatekeeper":{"media":{"uk":"media/uk/gatekeeper__gb_1.mp3","us":"media/us/gatekeeper__us_1.mp3"},"oxford":{"phon":"ˈɡeɪtkiːpə(r)","pos":"noun","senses":[{"en":"a person whose job is to check and control who is allowed to go through a gate","cn":"看门人；守门人；门卫"},{"en":"a person, system, etc. that decides whether somebody/something will be allowed, or allowed to reach a particular place or person","cn":"看门人；把关系统","ex":{"en":"His secretary acts as a gatekeeper, reading all mail before it reaches her boss.","cn":"老板的秘书负责把关，所有邮件都由她先过目再呈送给老板。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"看门人；守门人","en":"A gatekeeper is a person who is in charge of a gate and who allows people through it."}]},"examples":[{"en":"His secretary acts as a gatekeeper, reading all mail before it reaches her boss.","cn":"老板的秘书负责把关，所有邮件都由她先过目再呈送给老板。"}]},"gambling":{"media":{"uk":"media/uk/gambling__gb_1.mp3","us":"media/us/gambling__us_1.mp3"},"oxford":{"phon":"ˈɡæmblɪŋ","pos":"noun","senses":[{"en":"the activity of playing games of chance for money and of betting on horses, etc.","cn":"赌博；打赌；赌钱","ex":{"en":"online/internet gambling","cn":"线上／网络赌博"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"赌博；赌钱","en":"Gambling is the act or activity of betting money, for example in card games or on horse racing.","ex":{"en":"Gambling is a form of entertainment.","cn":"赌博是一种娱乐。"}}]},"examples":[{"en":"heavy gambling debts","cn":"沉重的赌债"},{"en":"The lottery is probably the most popular form of gambling.","cn":"彩票可能是最普遍的一种赌博形式。"}],"base":"gamble"},"gallon":{"media":{"uk":"media/uk/gallon__gb_1.mp3","us":"media/us/gallon__us_1.mp3"},"oxford":{"phon":"ˈɡælən","pos":"noun","senses":[{"en":"a unit for measuring liquid. In the UK, Canada and other countries it is equal to about 4.5 litres; in the US it is equal to about 3.8 litres. There are four quarts in a gallon.","cn":"加仑（液量单位，在英国、加拿大及其他一些国家约等于 4.5 升，在美国约等于 3.8 升，一加仑为四夸脱）","ex":{"en":"The tankers carried 130 000 gallons of fuel.","cn":"油轮装载了 130 000 加仑的燃料。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"加仑（液量单位，1加仑等于8品脱，英制等于4.564升，美制等于3.785升）","en":"A gallon is a unit of measurement for liquids that is equal to eight pints. In Britain, it is equal to 4.564 litres. In America, it is equal to 3.785 litres.","ex":{"en":"...80 million gallons of water a day.","cn":"每天8千万加仑水"}}]},"examples":[{"en":"The car does about 50 miles per gallon .","cn":"这辆车每加仑油能开50英里左右。"},{"en":"We drank gallons of coffee.","cn":"我们畅饮咖啡。"}]},"gasoline":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"同petrol","en":"Gasoline is the same as petrol ."}]},"media":{"uk":"media/uk/gasoline__gb_1.mp3","us":"media/us/gasoline__us_1.mp3"},"examples":[{"en":"I fill up the tank with gasoline about once a week.","cn":"我大约一个星期加满一箱汽油。"},{"en":"leaded/unleaded gasoline","cn":"含铅/无铅汽油"}],"oxford":{"phon":"ˈɡæsəliːn","pos":"noun","senses":[{"en":"a liquid obtained from petroleum, used as fuel in car engines, etc.","cn":"汽油","ex":{"en":"I fill up the tank with gasoline about once a week.","cn":"我大约一个星期加满一箱汽油。"}}]}},"gallantry":{"media":{"uk":"media/uk/gallantry__gb_1.mp3","us":"media/us/gallantry__us_1.mp3"},"oxford":{"phon":"ˈɡæləntri","pos":"noun","senses":[{"en":"courage, especially in a battle","cn":"（尤指在战场上）勇敢，英勇顽强","ex":{"en":"a medal for gallantry","cn":"英勇勋章"}},{"en":"polite attention given by men to women","cn":"（男子对女子的）殷勤","ex":{"en":"‘I like to think that gallantry isn’t dead,’ he said, kissing her hand.","cn":"“我认为，英勇还没有消亡，”他一边说，一边亲吻她的手。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"英勇；勇敢","en":"Gallantry is bravery shown by someone who is in danger, for example when they are fighting in a war.","ex":{"en":"For his gallantry he was awarded a Victoria Cross.","cn":"他因为表现英勇而荣获维多利亚十字勋章。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（尤指对女子的）殷勤，彬彬有礼","en":"Gallantry is kind, polite, and considerate behaviour towards other people, especially women.","ex":{"en":"It's that time of year again, when thoughts turn to romance and gallantry.","cn":"又到了每年的那个时候，人们又想到了风花雪月和献殷勤的男人。"}}]},"examples":[{"en":"a medal for gallantry","cn":"英勇勋章"}]},"game":{"media":{"uk":"media/uk/game__gb_1.mp3","us":"media/us/game__us_1.mp3"},"oxford":{"phon":"ɡeɪm","pos":"noun","senses":[{"en":"an activity that you do to have fun, often one that has rules and that you can win or lose; the equipment for a game","cn":"游戏；游戏机；游戏用具","g":"[countable]","sc":"fun","ex":{"en":"The kids were playing a game with their balloons.","cn":"孩子们正在用气球玩游戏。"}},{"en":"a sport with rules in which people or teams compete against each other","cn":"运动项目","g":"[countable]","sc":"sport","ex":{"en":"ball games, such as football or tennis","cn":"诸如足球或网球等球类运动"}},{"en":"an occasion of playing a game","cn":"（一项）游戏，运动，比赛","g":"[countable]","lab":"especially North American English","sc":"sport","ex":{"en":"to win/lose a game","cn":"赢／输一场比赛"}},{"en":"the way in which somebody plays a game","cn":"比赛（或游戏）时用的手法；比赛（或游戏）技巧","g":"[singular]","sc":"sport","ex":{"en":"Maguire raised his game to collect the £40 000 first prize.","cn":"马圭尔的比赛技巧有所提升，摘得 4 万英镑的一等奖。"}},{"en":"a large organized sports event","cn":"运动会","g":"[plural]","sc":"sport","ex":{"en":"She's hoping to participate in the next Olympic Games.","cn":"她希望参加下一届奥运会。"}},{"en":"sport as a lesson or an activity at school","cn":"（学校的）体育课，体育活动","g":"[plural]","lab":"old-fashioned, British English，，","sc":"sport","ex":{"en":"I always hated games at school.","cn":"我念书的时候一直不喜欢体育活动。"}},{"en":"a section of some games, such as tennis, which forms a unit in scoring","cn":"（网球等比赛的）一局，一场","g":"[countable]","sc":"sport","ex":{"en":"two games all (= both players have won two games)","cn":"各赢两局"}},{"en":"a type of activity or business","cn":"行当；行业；职业","g":"[countable]","sc":"activity/business","ex":{"en":"How long have you been in this game?","cn":"你干这行当多长时间了？"}},{"en":"a secret and clever plan; a trick","cn":"诡计；策略；花招","g":"[singular]","lab":"informal","sc":"secret plan","ex":{"en":"So that's his game (= now I know what he has been planning).","cn":"原来这就是他的鬼把戏。"}},{"en":"wild animals or birds that people hunt for sport or food","cn":"猎物；野禽；野味","g":"[uncountable]","sc":"wild animals/birds"},{"en":"to risk money playing a game of chance","cn":"赌博","g":"[intransitive]","pos":"verb"},{"en":"to play video games","cn":"玩电子游戏","g":"[intransitive]","pos":"verb"},{"en":"to use something in a way that is unfair but legal, in order to get what you want","cn":"不公平地利用；钻法律空子图利","g":"[transitive]","ex":{"en":"Some companies only received a government grant because they gamed the system.","cn":"一些公司钻了这个制度的空子而得到了政府补助。"},"pos":"verb"},{"en":"to treat somebody who trusts you in an unfair way in order to get what you want","cn":"不公平地对待；利用","g":"[transitive]","ex":{"en":"He gamed his publishers, his family and his friends in order to make a success of his autobiography.","cn":"为了使自己的自传成功，他利用了他的出版商、家人和朋友。"},"pos":"verb"},{"en":"ready and willing to do something new, difficult or dangerous","cn":"甘愿尝试；有冒险精神","ex":{"en":"She's game for anything.","cn":"她什么事都敢试。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"游戏；运动；比赛（项目）","en":"A game is an activity or sport usually involving skill, knowledge, or chance, in which you follow fixed rules and try to win against an opponent or to solve a puzzle.","ex":{"en":"...the wonderful game of football.","cn":"精彩的足球比赛"}},{"pos":"N-COUNT 可数名词","cn":"（一场）游戏，比赛","en":"A game is one particular occasion on which a game is played.","ex":{"en":"It was the first game of the season","cn":"这是本赛季的首场比赛。"}},{"pos":"N-COUNT 可数名词","cn":"（网球、桥牌等比赛中的）一局，一盘，一场","en":"A game is a part of a match, for example in tennis or bridge, consisting of a fixed number of points.","ex":{"en":"She won six games to love in the second set.","cn":"第二盘她以6比0获胜。"}},{"pos":"N-PLURAL 复数名词","cn":"运动会","en":"Games are an organized event in which competitions in several sports take place.","ex":{"en":"...the 2000 Olympic Games at Sydney.","cn":"2000年悉尼奥运会"}},{"pos":"N-PLURAL 复数名词","cn":"（学校的）体育课，体育活动","en":"Games are organized sports activities that children do at school.","ex":{"en":"At his grammar school he is remembered for being bad at games but good in debates.","cn":"在文法学校里，他因拙于体育但擅长辩论而让人印象深刻。"}},{"pos":"N-SING 单数名词","cn":"（某人比赛或游戏时的）手法，技巧，风格","en":"Someone's game is the degree of skill or the style that they use when playing a particular game.","ex":{"en":"Once I was through the first set my game picked up.","cn":"我打完第一局之后就进入了状态。"}},{"pos":"N-COUNT 可数名词","cn":"玩笑；儿戏；不认真对待的事情","en":"You can describe a situation that you do not treat seriously as a game .","ex":{"en":"Many people regard life as a game: you win some, you lose some","cn":"许多人视人生如同一场游戏：有输也有赢。"}},{"pos":"N-COUNT 可数名词","cn":"策略；计谋；诡计","en":"You can use game to describe a way of behaving in which a person uses a particular plan, usually in order to gain an advantage for himself or herself.","ex":{"en":"When the uncertainties become greater than the certainties, we end up in a game of bluff","cn":"情况愈发难以确定，我们最终陷入一个唬人的把戏中。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"猎物；野味","en":"Wild animals or birds that are hunted for sport and sometimes cooked and eaten are referred to as game .","ex":{"en":"...men who shot game for food.","cn":"靠捕猎获取食物的人"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"甘愿尝试（新鲜或不平常事物）的；有冒险精神的","en":"If you are game for something, you are willing to do something new, unusual, or risky.","ex":{"en":"After all this time he still had new ideas and was game to try them","cn":"过了这么久，他依然不乏新点子并敢于去尝试。"}},{"pos":"PHRASE 短语","cn":"泄露秘密；露马脚；露馅","en":"If someone or something gives the game away, they reveal a secret or reveal their feelings, and this puts them at a disadvantage.","ex":{"en":"The faces of the two conspirators gave the game away.","cn":"这两个共谋者的表情泄漏了秘密。"}},{"pos":"PHRASE 短语","cn":"对…不了解；缺乏经验","en":"If you are new to a particular game, you have not done a particular activity or been in a particular situation before.","ex":{"en":"Don't forget that she's new to this game and will take a while to complete the task.","cn":"别忘了她缺乏这方面的经验，完成任务还需要一些时间。"}},{"pos":"PHRASE 短语","cn":"卖淫；当妓女（或“鸭子”）","en":"If a man or woman is on the game, he or she is working as a prostitute."},{"pos":"PHRASE 短语","cn":"将计就计；以其人之道还治其人之身","en":"If you beat someone at their own game, you use the same methods that they have used, but more successfully, so that you gain an advantage over them.","ex":{"en":"He must anticipate the maneuvers of the other lawyers and beat them at their own game","cn":"他必须预见到其他律师的策略，并以其人之道还治其人之身，从而打败他们。"}},{"pos":"PHRASE 短语","cn":"（某种情况下）常有的事，司空见惯的事","en":"If you say that something is all part of the game, you are telling someone not to be surprised or upset by something, because it is a normal part of the situation that they are in.","ex":{"en":"For investors, risks are part of the game.","cn":"对投资者而言,风险不足为奇。"}},{"pos":"PHRASE 短语","cn":"不认真对待；耍花招；玩把戏","en":"If you say that someone is playing games or playing silly games, you mean that they are not treating a situation seriously and you are annoyed with them.","ex":{"en":"'Don't play games with me!' he thundered","cn":"“别跟我耍把戏!”他怒吼道。"}},{"pos":"PHRASE 短语","cn":"（通常在压力下）开始更好表现，干得更出色","en":"If you say that someone has raised their game, you mean that they have begun to perform better, usually because they were under pressure to do so.","ex":{"en":"The world No. 9 had to raise his game to see off a strong challenge from Dale","cn":"这位世界排名第九的选手必须有更出色的表现才能击退戴尔强有力的挑战。"}},{"pos":"PHRASE 短语","cn":"戏该收场了，别再演戏了（指所从事的秘密计划或活动被揭穿）","en":"If you say the game is up, you mean that someone's secret plans or activities have been revealed and therefore must stop because they cannot succeed.","ex":{"en":"Some thought they would hold out until Sunday. The realists knew that the game was already up.","cn":"有些人以为他们还能撑到星期天，务实的人却很清楚，这一切都已结束了。"}}]},"examples":[{"en":"We were losing 2–0 with ten minutes to go, and then we scored. It was game on!","cn":"离终场还有十分钟，我们以 0:2 落后，随后我们进球了。谁输谁赢还说不定呢！"},{"en":"Maguire raised his game to collect the £40 000 first prize.","cn":"马圭尔的比赛技巧有所提高，得到了 4 万英镑的头等奖。"}]},"gauze":{"media":{"uk":"media/uk/gauze__gb_1.mp3","us":"media/us/gauze__us_1.mp3"},"oxford":{"phon":"ɡɔːz","pos":"noun","senses":[{"en":"a type of light cloth that you can see through, usually made of cotton or silk","cn":"薄纱，纱罗（通常由棉或丝织成）","g":"[uncountable]"},{"en":"a type of thin cotton cloth used for covering and protecting wounds","cn":"纱布（包扎伤口用）","g":"[uncountable]","ex":{"en":"a gauze dressing","cn":"纱布敷料"}},{"en":"material made of a network of wire; a piece of this","cn":"（金属丝制的）网纱，网","g":"[uncountable, countable]","ex":{"en":"wire gauze","cn":"金属网纱"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"薄纱；纱布","en":"Gauze is a type of light, soft cloth with tiny holes in it.","ex":{"en":"Strain the juice through a piece of gauze or a sieve.","cn":"用一块纱布或过滤网将果汁过滤一下。"}}]},"examples":[{"en":"a gauze dressing","cn":"纱布敷料"},{"en":"wire gauze","cn":"金属网纱"}]},"gave":{"lemma":"give","media":{"uk":"media/uk/gave__gb_1.mp3","us":"media/us/gave__us_1.mp3"}},"gases":{"lemma":"gas","media":{"uk":"media/uk/gas__gb_1.mp3","us":"media/us/gas__us_1.mp3"}},"gather":{"media":{"uk":"media/uk/gather__gb_1.mp3","us":"media/us/gather__us_1.mp3"},"oxford":{"phon":"ˈɡæðə(r)","pos":"verb","senses":[{"en":"to come together, or bring people together, in one place to form a group","cn":"聚集；集合；召集","g":"[intransitive, transitive]","sc":"come/bring together","ex":{"en":"A crowd soon gathered.","cn":"很快就聚集起了一群人。"}},{"en":"to bring things together that have been spread around","cn":"收拢，归拢（分散的东西）","g":"[transitive]","sc":"come/bring together","ex":{"en":"People slowly gathered their belongings and left the hall.","cn":"人们慢慢地收起他们的随身物品离开了大厅。"}},{"en":"to collect information from different sources","cn":"搜集，收集（情报）","g":"[transitive]","sc":"collect","ex":{"en":"to gather information/data/intelligence","cn":"收集信息／数据／情报"}},{"en":"to collect plants, fruit, etc. from a wide area","cn":"采集（植物、水果等）","g":"[transitive]","sc":"collect","ex":{"en":"to gather wild flowers","cn":"采集野花"}},{"en":"to pick or cut and collect crops to be stored","cn":"收割；收获","g":"[transitive]","lab":"formal or literary","sc":"crops/harvest","ex":{"en":"It was late August and the harvest had been safely gathered in.","cn":"已是八月下旬，庄稼都妥善收割完毕。"}},{"en":"to believe or understand that something is true because of information or evidence you have","cn":"认为；猜想；推断；理解","g":"[transitive]","sc":"believe/understand","ex":{"en":"I gather (that) you wanted to see me.","cn":"我猜想你想要见我。"}},{"en":"to increase in speed, force, etc.","cn":"增加（速度、力量等）","g":"[transitive]","sc":"increase","ex":{"en":"The truck gathered speed.","cn":"卡车加快了速度。"}},{"en":"to gradually increase in number or amount","cn":"逐渐增加；积聚","g":"[intransitive]","sc":"of clouds/darkness","ex":{"en":"The storm clouds were gathering.","cn":"暴风雨乌云正在聚集。"}},{"en":"to pull a piece of clothing tighter to your body","cn":"收紧，拢起（衣服）","g":"[transitive]","sc":"clothing","ex":{"en":"He gathered his cloak around him.","cn":"他用披风把身子裹紧。"}},{"en":"to pull parts of a piece of clothing together in folds and sew them in place","cn":"给…打褶子","g":"[transitive]","sc":"clothing","ex":{"en":"She wore a skirt gathered (in) at the waist.","cn":"她穿了一条腰部打褶的裙子。"}},{"en":"to pull somebody towards you and put your arms around them","cn":"拢；拢住","g":"[transitive]","sc":"hold somebody","ex":{"en":"She gathered the child in her arms and held him close.","cn":"她把那男孩拢过来紧紧抱在怀里。"}},{"en":"to prepare yourself to do something that requires effort","cn":"攒（动）；使做好准备","g":"[transitive]","sc":"prepare yourself","ex":{"en":"I sat down for a moment to gather my strength.","cn":"我坐下片刻积蓄力量。"}},{"en":"to get your breath back after an effort","cn":"攒（动）；使做好准备","sc":"breath","ex":{"en":"He paused to gather his breath.","cn":"他停下来平复呼吸。"}}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"（使）聚集；（使）集合","en":"If people gather somewhere or if someone gathers people somewhere, they come together in a group.","ex":{"en":"In the evenings, we gathered around the fireplace and talked","cn":"晚上，我们聚在火炉边聊天。"}},{"pos":"VERB 动词","cn":"收集；收拢；归拢","en":"If you gather things, you collect them together so that you can use them.","ex":{"en":"I suggest we gather enough firewood to last the night","cn":"我建议大家捡足够多的木柴来撑过这一晚。"}},{"pos":"VERB 动词","cn":"（尤指经过一段时间的辛苦工作）收集，搜集（情报、证据等）","en":"If you gather information or evidence, you collect it, especially over a period of time and after a lot of hard work.","ex":{"en":"...a private detective using a hidden tape recorder to gather information","cn":"用暗藏的录音机搜集证据的私家侦探"}},{"pos":"VERB 动词","cn":"逐渐增加（速度、动力、力量等）","en":"If something gathers speed, momentum, or force, it gradually becomes faster or more powerful.","ex":{"en":"Demands for his dismissal have gathered momentum in recent weeks","cn":"最近几周，要求将他解职的呼声越来越高。"}},{"pos":"VERB 动词","cn":"集中（精力、思想等）；鼓起（勇气）；振作（精神）","en":"When you gather something such as your strength, courage, or thoughts, you make an effort to prepare yourself to do something.","ex":{"en":"You must gather your strength for the journey.","cn":"你必须为这次行程打起精神来。"}},{"pos":"VERB 动词","cn":"（用于引出已发现的信息，尤其是间接获得的信息）据我所知，据我了解","en":"You use gather in expressions such as 'I gather' and 'as far as I can gather' to introduce information that you have found out, especially when you have found it out in an indirect way.","ex":{"en":"I gather his report is highly critical of the trial judge","cn":"据我所知，他在报道中毫不留情地批评了初审法官。"}},{"pos":"VERB 动词","cn":"给…打褶","en":"If you gather fabric or cloth, you make a row of very small folds in it by sewing a thread through it and then pulling the thread tight.","ex":{"en":"Gather the skirt at the waist.","cn":"在裙子的腰部打褶。"}},{"pos":"","cn":"","en":"to gather dust→see: ;"},{"pos":"","cn":"","en":"相关词组：gather up"}]},"examples":[{"en":"During the 1980s the green movement gathered momentum. * 20","cn":"世纪 80 年代期间绿色运动的势头开始增强。"},{"en":"People slowly gathered their belongings and left the hall.","cn":"人们慢慢地收起他们的随身物离开了大厅。"}]},"gallery":{"oxford":{"phon":"ˈɡæləri","pos":"noun","senses":[{"en":"a room or building for showing works of art, especially to the public","cn":"（艺术作品的）陈列室，展览馆","lab":"US English","ex":{"en":"a picture gallery","cn":"美术馆"}},{"en":"a collection of pictures","cn":"图片库","ex":{"en":"Visit the photo gallery on our website to see pictures from the event.","cn":"请访问我们网站的图片库，查看活动照片。"}},{"en":"a small private shop where you can see and buy works of art","cn":"（经营性）画廊"},{"en":"an upstairs area at the back or sides of a large hall where people can sit","cn":"（大厅的）楼座，楼上旁听席","ex":{"en":"Relatives of the victim watched from the public gallery as the murder charge was read out in court.","cn":"法庭宣读谋杀指控时受害者的亲属在公共旁听席观看。"}},{"en":"the highest level in a theatre where the cheapest seats are","cn":"（剧场中票价最低的）顶层楼座"},{"en":"a long narrow room, especially one used for a particular purpose","cn":"长廊；走廊；柱廊"},{"en":"a level passage under the ground in a mine or cave","cn":"（矿坑或洞穴中的）水平巷道"}]},"collins":{"senses":[{"pos":"N-COUNT; N-IN-NAMES 名称名词；名称名词","cn":"（艺术作品的）陈列室，展览馆；画廊","en":"A gallery is a place that has permanent exhibitions of works of art in it.","ex":{"en":"...an art gallery.","cn":"美术馆"}},{"pos":"N-COUNT 可数名词","cn":"私人画店；私人画廊（或画室）","en":"A gallery is a privately owned building or room where people can look at and buy works of art.","ex":{"en":"The painting is in the gallery upstairs.","cn":"那幅画在楼上的画廊里。"}},{"pos":"N-COUNT 可数名词","cn":"（大厅的）楼座，边座，楼上旁听席","en":"A gallery is an area high above the ground at the back or at the sides of a large room or hall.","ex":{"en":"A crowd already filled the gallery.","cn":"楼座已经挤满了人。"}},{"pos":"N-COUNT 可数名词","cn":"（剧场或音乐厅中通常票价最低的）顶层楼座","en":"The gallery in a theatre or concert hall is an area high above the ground that usually contains the cheapest seats.","ex":{"en":"They had been forced to find cheap tickets in the gallery.","cn":"他们不得已买了顶层楼座的廉价票。"}}]},"media":{"uk":"media/uk/gallery__gb_1.mp3","us":"media/us/gallery__us_1.mp3"},"examples":[{"en":"Relatives of the victim watched from the public gallery as the murder charge was read out in court.","cn":"法庭宣读谋杀指控时受害者的亲属在公共旁听席观看。"},{"en":"an art/a picture gallery","cn":"美术馆；绘画陈列室"}]},"gaze":{"media":{"uk":"media/uk/gaze__gb_1.mp3","us":"media/us/gaze__us_1.mp3"},"oxford":{"phon":"ɡeɪz","pos":"verb","senses":[{"en":"to look steadily at somebody/something for a long time, either because you are very interested or surprised, or because you are thinking of something else","cn":"凝视；注视；盯着","ex":{"en":"She gazed at him in amazement.","cn":"她惊异地注视着他。"}},{"en":"a long, steady look at somebody/something","cn":"凝视；注视","ex":{"en":"He met her gaze (= looked at her while she looked at him).","cn":"他与她凝视的目光相遇。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"凝视；注视；盯着看","en":"If you gaze at someone or something, you look steadily at them for a long time, for example because you find them attractive or interesting, or because you are thinking about something else.","ex":{"en":"She stood gazing at herself in the mirror","cn":"她站在那儿，凝视着镜中的自己。"}},{"pos":"N-COUNT 可数名词","cn":"凝视；注视","en":"You can talk about someone's gaze as a way of describing how they are looking at something, especially when they are looking steadily at it.","ex":{"en":"The Monsignor turned his gaze from the flames to meet the Colonel's","cn":"这位大人凝视的目光离开火苗，与上校的目光相遇。"}},{"pos":"PHRASE 短语","cn":"受公众关注；受人瞩目","en":"If someone or something is in the public gaze, they are receiving a lot of attention from the general public.","ex":{"en":"You won't find a couple more in the public gaze than Michael and Lizzie.","cn":"没有比迈克尔和莉齐更受人瞩目的夫妇了。"}}]},"examples":[{"en":"He sat for hours just gazing into space.","cn":"他一连几个小时坐在那里茫然地看着前面。"},{"en":"He met her gaze (= looked at her while she looked at him).","cn":"他与她凝视的目光相遇。"}]},"gang":{"media":{"uk":"media/uk/gang__gb_1.mp3","us":"media/us/gang__us_1.mp3"},"oxford":{"phon":"ɡæŋ","pos":"noun","senses":[{"en":"an organized group of criminals","cn":"一帮，一伙（罪犯）","ex":{"en":"criminal gangs","cn":"犯罪团伙"}},{"en":"a group of young people who spend a lot of time together and often cause trouble or fight against other groups","cn":"一帮，一群，一伙（闹事、斗殴的年轻人）","ex":{"en":"to join a gang","cn":"加入团伙"}},{"en":"a group of friends who meet regularly","cn":"一伙（经常聚在一起的朋友）","lab":"informal","ex":{"en":"The whole gang will be there.","cn":"大伙儿都将在那儿。"}},{"en":"an organized group of workers or prisoners doing work together","cn":"一队，一组（一起干活的工人或囚犯）","ex":{"en":"a prison/work gang","cn":"狱内团伙；劳动队"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"一帮，一伙（尤指滋事的年轻人）","en":"A gang is a group of people, especially young people, who go around together and often deliberately cause trouble.","ex":{"en":"During the fight with a rival gang he lashed out with his flick knife","cn":"在与敌对帮派的打斗中，他挥舞着弹簧折刀一通猛刺。"}},{"pos":"N-COUNT 可数名词","cn":"一帮，一伙（罪犯）","en":"A gang is a group of criminals who work together to commit crimes.","ex":{"en":"Police were hunting for a gang who had allegedly stolen fifty-five cars.","cn":"警方正在追捕一个被控盗窃了55辆汽车的犯罪团伙。"}},{"pos":"N-SING 单数名词","cn":"一伙（常聚会的朋友）","en":"The gang is a group of friends who frequently meet.","ex":{"en":"Come on over, we've got lots of the old gang here.","cn":"过来吧，好多老朋友都在这儿。"}},{"pos":"N-COUNT 可数名词","cn":"一群，一队，一组（一起干体力活的人）","en":"A gang is a group of workers who do physical work together.","ex":{"en":"...a gang of labourers.","cn":"一群工人"}},{"pos":"","cn":"","en":"相关词组：gang up"}]},"examples":[{"en":"At school the older boys ganged up on him and called him names.","cn":"在学校读书时那些大男孩联合起来欺负他，辱骂他。"},{"en":"A four-man gang carried out the robbery.","cn":"这起抢劫是一个四人团伙所为。"}]},"gaining":{"lemma":"gain","media":{"uk":"media/uk/gain__gb_1.mp3","us":"media/us/gain__us_1.mp3"}},"gaps":{"lemma":"gap","media":{"uk":"media/uk/gap__gb_1.mp3","us":"media/us/gap__us_1.mp3"}},"galley":{"media":{"uk":"media/uk/galley__gb_1.mp3","us":"media/us/galley__us_1.mp3"},"oxford":{"phon":"ˈɡæli","pos":"noun","senses":[{"en":"a long flat ship with sails, especially one used by the ancient Greeks or Romans in war, usually rowed by slaves or prisoners","cn":"（常由奴隶或囚犯划桨的）桨帆船；（古希腊和古罗马的）战舰","ex":{"en":"a galley slave","cn":"划桨的奴隶"}},{"en":"the kitchen on a ship or plane","cn":"（船或飞机上的）厨房"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（轮船或飞机上的）厨房","en":"On a ship or aircraft, the galley is the kitchen."},{"pos":"N-COUNT 可数名词","cn":"（旧时常由奴隶或囚犯划桨的）桨帆船","en":"In former times, a galley was a ship with sails and a lot of oars, which was often rowed by slaves or prisoners."}]},"examples":[{"en":"The fire extinguishers are stored in the galley.","cn":"灭火器存放在船上的厨房里。"}]},"gain":{"media":{"uk":"media/uk/gain__gb_1.mp3","us":"media/us/gain__us_1.mp3"},"oxford":{"phon":"ɡeɪn","pos":"verb","senses":[{"en":"to obtain or win something, especially something that you need or want","cn":"获得；赢得；博得；取得","g":"[transitive]","sc":"obtain/win","ex":{"en":"They managed to gain access to secret files.","cn":"他们设法访问秘密文件。"}},{"en":"to obtain an advantage or benefit from something or from doing something","cn":"（从…中）受益，获益；得到（好处）","g":"[transitive, intransitive]","sc":"obtain/win","ex":{"en":"The firm is hoping to gain an advantage over its competitors.","cn":"这家公司希望能够胜过竞争对手一筹。"}},{"en":"to gradually get more of something","cn":"增加；增添；增进；增长","g":"[transitive]","sc":"get more","ex":{"en":"As you gain experience, you will grow in confidence.","cn":"随着你逐渐积累经验，你将会变得更加自信。"}},{"en":"to go too fast (by a particular amount of time)","cn":"走得快（若干时间）","g":"[transitive, intransitive]","sc":"of watch/clock","ex":{"en":"My watch gains two minutes every 24 hours.","cn":"我的表每 24 小时快两分钟。"}},{"en":"to increase in value","cn":"增值；升值","g":"[transitive, intransitive]","sc":"of currencies/shares","ex":{"en":"The shares gained 14p to 262p.","cn":"股价上升了 14 便士，收报 262 便士。"}},{"en":"to reach a place, usually after a lot of effort","cn":"（经过努力）到达","g":"[transitive]","lab":"formal","sc":"reach place","ex":{"en":"At last she gained the shelter of the forest.","cn":"她终于到达了森林中的隐蔽处。"}},{"en":"an increase in the amount of something, especially in wealth or weight","cn":"（尤指财富、重量的）增值，增加","g":"[countable, uncountable]","sc":"increase","ex":{"en":"The opposition made unexpected gains in the last election.","cn":"反对党在最近的选举中取得了意外收获。"},"pos":"noun"},{"en":"an advantage or improvement","cn":"好处；利益；改进","g":"[countable]","sc":"advantage","ex":{"en":"Our loss is their gain.","cn":"我们之所失即他们之所得。"},"pos":"noun"},{"en":"financial profit","cn":"利润；经济收益","g":"[uncountable]","lab":"often disapproving","sc":"profit","ex":{"en":"He only seems to be interested in personal gain.","cn":"他似乎只在乎个人的收益。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"获得；博得；赢得","en":"If a person or place gains something such as an ability or quality, they gradually get more of it.","ex":{"en":"Students can gain valuable experience by working on the campus radio or magazine","cn":"学生们在校广播台或校刊工作能够获得宝贵的经验。"}},{"pos":"VERB 动词","cn":"（从…中）受益,获益,得到好处","en":"If you gain from something such as an event or situation, you get some advantage or benefit from it.","ex":{"en":"The company didn't disclose how much it expects to gain from the two deals","cn":"这家公司未透露这两笔交易的预期获利情况。"}},{"pos":"VERB 动词","cn":"增加（体重、速度等）","en":"To gain something such as weight or speed means to have an increase in that particular thing.","ex":{"en":"Some people do gain weight after they stop smoking","cn":"一些人戒烟后体重确实会增加。"}},{"pos":"VERB 动词","cn":"（尤指经努力）获得，取得","en":"If you gain something, you obtain it, especially after a lot of hard work or effort.","ex":{"en":"They realise that passing exams is no longer enough to gain a place at university","cn":"他们认识到现在仅仅是考试通过，并不能确保进入大学。"}},{"pos":"PHRASE 短语","cn":"为了获得利益；为了获得好处","en":"If you do something for gain, you do it in order to get some advantage or profit for yourself, and for no other reason.","ex":{"en":"...buying art solely for financial gain.","cn":"纯粹为了赚钱而购买艺术品"}},{"pos":"PHRASE 短语","cn":"（想法、理想等）越来越流行，逐渐为人接受","en":"If something such as an idea or an ideal gains ground, it gradually becomes more widely known or more popular.","ex":{"en":"There are strong signs that his views are gaining ground","cn":"各种明显的迹象显示他的观点越来越受欢迎。"}},{"pos":"PHRASE 短语","cn":"赢得时间；争取时间","en":"If you do something in order to gain time, you do it in order to give yourself enough time to think of an excuse or a way out of a difficult situation.","ex":{"en":"I hoped to gain time by keeping him talking.","cn":"我希望让他一直说下去以争取时间。"}},{"pos":"","cn":"","en":"相关词组：gain on"}]},"examples":[{"en":"The shares gained 14p to 262p.","cn":"股价上升了 14 便士，收报 262 便士。"},{"en":"a £3 000 gain from our investment","cn":"从我们的投资中获取的 3 000 英镑的收益"}]},"galleries":{"lemma":"gallery"},"garden":{"media":{"img":["media/pic/garden_labels_comp.jpg","media/thumb/garden.jpg"],"uk":"media/uk/garden__gb_1.mp3","us":"media/us/garden__us_1.mp3"},"oxford":{"phon":"ˈɡɑːdn","pos":"noun","senses":[{"en":"a piece of land next to or around your house where you can grow flowers, fruit, vegetables, etc., usually with a lawn (= an area of grass)","cn":"（住宅旁或周围的）园圃，花园，果园，菜园","g":"[countable]","lab":"British English","ex":{"en":"a front/back/rear garden","cn":"前／后花园"}},{"en":"an area in a yard where you grow flowers or plants","cn":"庭园；园子","g":"[countable]","lab":"North American English","ex":{"en":"These flowers brighten up backyard gardens all over the country.","cn":"这些花为全国各地的后花园增色不少。"}},{"en":"a public park","cn":"公园","g":"[countable]","ex":{"en":"Thousands of people now visit the gardens every year.","cn":"现在每年都有成千上万人来公园游览。"}},{"en":"used in the name of streets","cn":"（用于街名）园，街，广场","g":"[singular]","lab":"British English","ex":{"en":"39 Belvoir Gardens","cn":"贝尔沃街 39 号"}},{"en":"to work in a garden","cn":"做园艺工作；种植花木","ex":{"en":"More people are choosing to garden organically.","cn":"越来越多的人选择有机园艺。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（住宅旁的）花园，菜园，庭园，园子（美国英语中表示此义时常用yard，而garden仅用来指花园和菜园）","en":"In British English, a garden is a piece of land next to a house, with flowers, vegetables, other plants, and often grass. In American English, the usual word is yard, and a garden refers only to land which is used for growing flowers and vegetables.","ex":{"en":"...the most beautiful garden on Earth.","cn":"世界上最漂亮的花园"}},{"pos":"VERB 动词","cn":"干园艺活；种植花木","en":"If you garden, you do work in your garden such as weeding or planting.","ex":{"en":"Jim gardened at the homes of friends on weekends.","cn":"吉姆周末帮忙打理朋友家的花园。"}},{"pos":"N-PLURAL 复数名词","cn":"公园","en":"Gardens are places like a park that have areas of plants, trees, and grass, and that people can visit and walk around.","ex":{"en":"The Gardens are open from 10.30am until 5pm.","cn":"公园从上午10点半到下午5点之间开放。"}},{"pos":"N-IN-NAMES 名称名词","cn":"（用于街名）园，街，广场","en":"Gardens is sometimes used as part of the name of a street.","ex":{"en":"He lives at 9, Acacia Gardens.","cn":"他住在金合欢街9号。"}}]},"examples":[{"en":"We employ a gardener two days a week.","cn":"我们雇了个花匠，每周工作两天。"},{"en":"My wife's a keen gardener.","cn":"我的妻子是个热衷园艺的人。"}]},"gauge":{"media":{"uk":"media/uk/gauge__gb_1.mp3","us":"media/us/gauge__us_1.mp3","img":["media/ldoce/img/gauge.jpg"]},"oxford":{"phon":"ɡeɪdʒ","pos":"noun","senses":[{"en":"an instrument for measuring the amount or level of something","cn":"测量仪器（或仪表）；计量器","ex":{"en":"a fuel/pressure/temperature gauge","cn":"燃油表；压力表；温度计"}},{"en":"a measurement of how wide or thick something is","cn":"宽度；厚度","ex":{"en":"What gauge of wire do we need?","cn":"我们需要多大直径的金属丝？"}},{"en":"a measurement of how wide the barrel of a gun is","cn":"（枪管的）口径","lab":"especially in British English","ex":{"en":"a 12-gauge shotgun","cn":"12 号猎枪"}},{"en":"the distance between the rails of a railway track or the wheels of a train","cn":"（铁道的）轨距；（火车的）轮距","ex":{"en":"standard gauge (= 56½ inches in Britain)","cn":"标准轨距（等于英制的 56.5 英寸）"}},{"en":"a fact or an event that can be used to estimate or judge something","cn":"（用于估计或判断的）事实，依据，尺度，标准","g":"[usually singular]","ex":{"en":"Tomorrow's game against Arsenal will be a good gauge of their promotion chances.","cn":"明天与阿森纳队的比赛是衡量他们能否晋级的很好依据。"}},{"en":"to make a judgement about something, especially people’s feelings or attitudes","cn":"判定，判断（尤指人的感情或态度）","ex":{"en":"They interviewed employees to gauge their reaction to the changes.","cn":"他们与雇员面谈以判定他们的应变能力。"},"pos":"verb"},{"en":"to measure something accurately using a special instrument","cn":"（用仪器）测量","ex":{"en":"precision instruments that can gauge the diameter to a fraction of a millimetre","cn":"可测出直径为若干分之一毫米的精密仪器"},"pos":"verb"},{"en":"to calculate something approximately","cn":"估计；估算","ex":{"en":"We were able to gauge the strength of the wind from the movement of the trees.","cn":"我们可根据树的摇动估算出风力。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"（常指用某种仪器）测量，测定，算出","en":"If you gauge the speed or strength of something, or if you gauge an amount, you measure or calculate it, often by using a device of some kind.","ex":{"en":"He gauged the wind at over thirty knots","cn":"他测出风速在30节以上。"}},{"pos":"N-COUNT 可数名词","cn":"测量仪器；计量仪","en":"A gauge is a device that measures the amount or quantity of something and shows the amount measured.","ex":{"en":"...temperature gauges.","cn":"温度计"}},{"pos":"VERB 动词","cn":"判断，判定（人的行动、情感或意图）","en":"If you gauge people's actions, feelings, or intentions in a particular situation, you carefully consider and judge them.","ex":{"en":"...as he gauged possible enemy moves and his own responses","cn":"他在盘算着敌人可能的动向和自己的对策时"}},{"pos":"N-SING 单数名词","cn":"（评价或判断的）事实，依据，标准","en":"A gauge of someone's feelings or a situation is a fact or event that can be used to judge them.","ex":{"en":"The index is the government's chief gauge of future economic activity.","cn":"这一指数是政府判断未来经济活动的主要依据。"}},{"pos":"N-COUNT 可数名词","cn":"（铁道的）轨距","en":"A gauge is the distance between the two rails on a railway line.","ex":{"en":"...a narrow gauge railway.","cn":"窄轨铁路"}},{"pos":"N-COUNT 可数名词","cn":"（金属等的）厚度；（金属丝等的）直径","en":"A gauge is the thickness of something, especially metal or wire."}]},"examples":[{"en":"Tomorrow's game against Arsenal will be a good gauge of their promotion chances.","cn":"明天与阿森纳队的比赛是衡量他们能否升级的很好依据。"},{"en":"standard gauge (= 56½ inches in Britain)","cn":"标准轨距（在英国为 56.5 英寸）"}]},"gait":{"media":{"uk":"media/uk/gait__gb_1.mp3","us":"media/us/gait__us_1.mp3"},"oxford":{"phon":"ɡeɪt","pos":"noun","senses":[{"en":"a way of walking or running","cn":"步态；步法","ex":{"en":"He walked with a rolling gait.","cn":"他走起路来摇摇晃晃。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"步态；步法","en":"A particular kind of gait is a particular way of walking.","ex":{"en":"...a tubby little man in his fifties, with sparse hair and a rolling gait","cn":"一位50多岁的矮胖男子，头发稀疏，走路晃晃悠悠"}}]},"examples":[{"en":"He walked with a rolling gait.","cn":"他走起路来摇摇晃晃。"},{"en":"a slow shuffling gait","cn":"迟缓拖沓的步子"}]},"gas":{"media":{"uk":"media/uk/gas__gb_1.mp3","us":"media/us/gas__us_1.mp3"},"oxford":{"phon":"ɡæs","pos":"noun","senses":[{"en":"any substance like air that is neither a solid nor a liquid, for example hydrogen or oxygen","cn":"气体","g":"[countable, uncountable]","sc":"not solid/liquid","ex":{"en":"Air is a mixture of gases.","cn":"空气为混合气体。"}},{"en":"a particular type of gas or mixture of gases used as fuel for heating and cooking","cn":"气体燃料；煤气；天然气","g":"[uncountable]","lab":"British English","sc":"not solid/liquid","ex":{"en":"fossil fuels like oil and gas","cn":"石油和天然气等化石燃料"}},{"en":"a particular type of gas used during a medical operation, to make the patient unconscious or to make the pain less","cn":"（外科手术用）麻醉气","g":"[uncountable]","sc":"not solid/liquid","ex":{"en":"an anaesthetic gas","cn":"麻醉气体"}},{"en":"a particular type of gas used in war to kill or injure people, or used by the police to control people","cn":"（战争用）毒气；（警察用）瓦斯","g":"[uncountable]","sc":"not solid/liquid","ex":{"en":"a gas attack","cn":"毒气攻击"}},{"en":"a liquid obtained from petroleum, used as fuel in car engines, etc.","cn":"汽油","g":"[uncountable]","lab":"both North American English","sc":"in vehicle","ex":{"en":"to run out of gas","cn":"汽油用完了"}},{"en":"the pedal in a car or other vehicle that you press with your foot to control the speed of the engine","cn":"（汽车等的）油门踏板，加速装置","g":"[singular]","lab":"both especially North American English","sc":"in vehicle","ex":{"en":"Step on the gas, we're late.","cn":"踩油门开快点，我们要迟到了。"}},{"en":"a person or an event that is fun","cn":"有趣的人（或事物）","g":"[singular]","lab":"especially North American English","sc":"fun","ex":{"en":"The party was a real gas.","cn":"这次聚会真有趣。"}},{"en":"air that you swallow with food or drink; gas that is produced in your stomach or intestines that makes you feel uncomfortable","cn":"（随食物或饮料）吞下的气；胃气；肠气","g":"[uncountable]","lab":"North American English","sc":"in stomach"},{"en":"to kill or harm somebody by making them breathe poisonous gas","cn":"用毒气杀伤；使吸入毒气","g":"[transitive]","sc":"kill/harm with gas","ex":{"en":"She gassed herself with fumes from the car’s exhaust pipe.","cn":"她用汽车排气管排出的烟雾给自己加油。"},"pos":"verb"},{"en":"to talk for a long time about things that are not important","cn":"闲聊；空谈；瞎扯","g":"[intransitive]","lab":"old-fashioned, informal，，","sc":"talk","ex":{"en":"I thought he’d never stop gassing!","cn":"我以为他永远不会停止放气！"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"气体燃料；天然气；煤气","en":"Gas is a substance like air that is neither liquid nor solid and burns easily. It is used as a fuel for cooking and heating.","ex":{"en":"Coal is actually cheaper than gas","cn":"煤实际上比煤气便宜。"}},{"pos":"N-VAR 可变名词","cn":"气体","en":"A gas is any substance that is neither liquid nor solid, for example oxygen or hydrogen.","ex":{"en":"Helium is a very light gas.","cn":"氦是一种非常轻的气体。"}},{"pos":"N-MASS 物质名词","cn":"毒气，瓦斯（可用作武器）","en":"Gas is a poisonous gas that can be used as a weapon.","ex":{"en":"...mustard gas","cn":"芥子气"}},{"pos":"N-MASS 物质名词","cn":"（医用）麻醉气","en":"Gas is a gas used for medical purposes, for example to make patients feel less pain or go to sleep during an operation.","ex":{"en":"...an anaesthetic gas used by many dentists.","cn":"为许多牙医使用的一种麻醉气"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（车辆用的）汽油","en":"Gas is the fuel which is used to drive motor vehicles.","ex":{"en":"...a tank of gas.","cn":"一桶汽油"}},{"pos":"VERB 动词","cn":"用毒气杀死","en":"To gas a person or animal means to kill them by making them breathe poisonous gas.","ex":{"en":"Her husband ran a pipe from her car exhaust to the bedroom in an attempt to gas her.","cn":"她的丈夫将一根与她的汽车排气管相通的管子导入卧室，企图用毒气将她杀死。"}},{"pos":"N-SING 单数名词","cn":"活泼有趣的事；令人愉快的场面","en":"You can describe a situation or event as a gas when it is very lively, amusing, and enjoyable.","ex":{"en":"It was really a gas to find someone I could talk with.","cn":"找到一个能和我谈得来的人真是一件让人高兴的事。"}},{"pos":"PHRASE 短语","cn":"加大油门；加速","en":"If you step on the gas when you are driving a vehicle, you go faster."}]},"examples":[{"en":"During the birth she was given gas and air.","cn":"她分娩时医生给她吸了麻醉气。"},{"en":"Step on the gas, we're late.","cn":"加大油门，我们要迟到了。"}]},"gates":{"lemma":"gate"},"gardener":{"media":{"uk":"media/uk/gardener__gb_1.mp3","us":"media/us/gardener__us_1.mp3"},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"花匠；园丁；园艺工人","en":"A gardener is a person who is paid to work in someone else's garden."},{"pos":"N-COUNT 可数名词","cn":"喜欢干园艺活的人","en":"A gardener is someone who enjoys working in their own garden growing flowers or vegetables.","ex":{"en":"...enthusiastic amateur gardeners.","cn":"热衷园艺的业余爱好者"}}]},"examples":[{"en":"We employ a gardener two days a week.","cn":"我们雇了个花匠，每周工作两天。"},{"en":"My wife's a keen gardener.","cn":"我的妻子是个热衷园艺的人。"}],"oxford":{"phon":"ˈɡɑːdnə(r)","pos":"noun","senses":[{"en":"a person whose job is to work in a garden","cn":"园艺工人，园丁，花匠","ex":{"en":"We employ a gardener two days a week.","cn":"我们雇了个花匠，每周工作两天。"}},{"en":"a person who enjoys working in a garden","cn":"园艺爱好者","ex":{"en":"My wife's a keen gardener.","cn":"我妻子是个热衷园艺的人。"}}]}},"gatherings":{"lemma":"gather"},"gaudy":{"media":{"uk":"media/uk/gaudy__gb_1.mp3","us":"media/us/gaudy__us_1.mp3"},"oxford":{"phon":"ˈɡɔːdi","pos":"adjective","senses":[{"en":"too brightly coloured in a way that lacks taste","cn":"俗艳的；花哨的","ex":{"en":"gaudy clothes/colours","cn":"过于花哨的衣服／色彩"}},{"en":"the name used in some colleges at the universities of Oxford and Cambridge for the special dinner for former students that takes place each year","cn":"艳丽：每年在牛津大学和剑桥大学的一些大学中使用的名称，用于为前生举办的特别晚宴","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"花哨的；俗艳的","en":"If something is gaudy, it is very brightly-coloured and showy.","ex":{"en":"...her gaudy orange-and-purple floral hat.","cn":"她那顶饰有花卉的橙紫相间的花哨帽子"}}]},"examples":[{"en":"gaudy clothes/colours","cn":"过于花哨的衣服/色彩"},{"en":"gaudily dressed/painted","cn":"穿着/涂饰得太俗艳"}]},"gardens":{"lemma":"garden"},"garages":{"lemma":"garage"},"gasping":{"lemma":"gasp"},"gallons":{"lemma":"gallon"},"gained":{"lemma":"gain"},"gangs":{"lemma":"gang"},"gambler":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"赌徒；赌棍","en":"A gambler is someone who gambles regularly, for example in card games or horse racing."},{"pos":"N-COUNT 可数名词","cn":"冒险主义者；投机者","en":"If you describe someone as a gambler, you mean that they are ready to take risks in order to gain advantages or success.","ex":{"en":"He had never been afraid of failure: he was a gambler, ready to go off somewhere else and start all over again.","cn":"他从来都不害怕失败：他是个冒险家，随时准备到别处从头再来。"}}]},"media":{"uk":"media/ldoce/hwd/bre/e/gamble_v0205.mp3","us":"media/ldoce/hwd/ame/1/gamble1.mp3"},"examples":[{"en":"Their religion forbids them to drink or gamble.","cn":""},{"en":"Jack loves gambling on the horses.","cn":""}],"oxford":{"phon":"ˈɡæmblə(r)","pos":"noun","senses":[{"en":"a person who risks money on a card game, horse race, etc.","cn":"（牌戏、赛马等中）赌博，打赌","ex":{"en":"He was a compulsive gambler (= found it difficult to stop).","cn":"他嗜赌成性。"}},{"en":"a person who is willing to risk losing something in the hope of being successful","cn":"冒风险；碰运气；以…为赌注","ex":{"en":"She is an eternal optimist and gambler at heart.","cn":"她是一个永远的乐观主义者和内心的赌徒。"}}]}},"gains":{"lemma":"gain"},"gazing":{"lemma":"gaze"},"gardeners":{"lemma":"gardener"},"gathered":{"lemma":"gather"},"garnished":{"oxford":{"phon":"ˈɡɑːnɪʃ","pos":"verb","senses":[{"en":"to decorate a dish of food with a small amount of another food （","cn":"用菜）为（食物）加装饰；加饰菜于"},{"en":"a small amount of food that is used to decorate a larger dish of food （","cn":"食物上的）装饰菜"}]}},"gazed":{"lemma":"gaze"},"games":{"lemma":"game"},"gash":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"深长的伤口（或切口）","en":"A gash is a long, deep cut in your skin or in the surface of something.","ex":{"en":"There was an inch-long gash just above his right eye.","cn":"就在他右眼的上方有一条一英寸长的伤口。"}},{"pos":"VERB 动词","cn":"划伤；砍伤","en":"If you gash something, you accidentally make a long and deep cut in it.","ex":{"en":"He gashed his leg while felling trees.","cn":"他砍树的时候砍伤了腿。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"damage to part of your body caused by an accident or an attack","cn":""},{"en":"an injury, especially a deep cut in your skin made by a knife, bullet, or bomb","cn":""},{"en":"a small injury made when a sharp object cuts your skin","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"A gash is a deep cut, like a gash on your knee from a biking accident, or a gash in the earth caused by workers who are digging up a broken sewer."}]},"collocations":{"phrases":["ADJ. deep, great, long | nasty, terrible","VERB + GASH get, have","PREP. on the ~ She got a nasty gash on the head. 2 large hole","ADJ. deep, great, long","VERB + GASH carve, cut, tear The bulldozers carved a great gash through the forest. The rocks tore a long gash in the ship's hull."]},"media":{"uk":"media/ldoce/hwd/bre/1/gash0205.mp3","us":"media/ldoce/hwd/ame/8/gash.mp3"},"examples":[{"en":"He gashed his hand on a sharp piece of rock.","cn":"他的手在一块尖石头上划了一个大口子。"},{"en":"Blood poured from a deep gash in her forehead.","cn":"鲜血从她额头上一道很深的伤口汩汩地流出来。"}],"oxford":{"phon":"ɡæʃ","pos":"noun","senses":[{"en":"a long deep cut in the surface of something, especially a person’s skin","cn":"深长的切口（或伤口、划伤）","ex":{"en":"He needed an operation to close a nasty gash in his arm.","cn":"他需要接受手术来缝合手臂上的一道严重伤口。"}},{"en":"to make a long deep cut in something, especially a person’s skin","cn":"划伤，砍伤（尤指人的皮肤）","ex":{"en":"He gashed his hand on a sharp piece of rock.","cn":"他的手在一块尖石头上划了一个大口子。"},"pos":"verb"}]}},"gangrene":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"坏疽","en":"Gangrene is the decay that can occur in a part of a person's body if the blood stops flowing to it, for example as a result of illness or injury.","ex":{"en":"Once gangrene has developed the tissue is dead.","cn":"一旦出现坏疽，机体组织便已死亡。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a condition in which your flesh decays in part of your body, because blood has stopped flowing there as a result of illness or injury","cn":"坏疽"}]},"vocab":{"pos":"n v","senses":[{"en":"You don't want gangrene, that's for sure. It's the infection that can develop around a wound that kills the tissue, turning it into a terrible stinking sore."}]},"collocations":{"phrases":["VERB + GANGRENE have, suffer from | develop","GANGRENE + VERB set in The wound was not properly disinfected and gangrene set in. •"]},"media":{"uk":"media/ldoce/hwd/bre/2/gangrene0205.mp3","us":"media/ldoce/hwd/ame/4/gangrene.mp3"},"examples":[{"en":"Gangrene set in and he had to have his leg amputated.","cn":"他的腿生了坏疽，必须截除。"}],"oxford":{"phon":"ˈɡæŋɡriːn","pos":"noun","senses":[{"en":"the decay (= a process of being destroyed) that takes place in a part of the body when the blood supply to it has been stopped because of an illness or injury","cn":"坏疽","ex":{"en":"Gangrene set in and he had to have his leg amputated.","cn":"他的腿生了坏疽，必须截除。"}}]}},"gallop":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"（使）（马）飞奔；（使）（马）疾驰","en":"When a horse gallops, it runs very fast so that all four legs are off the ground at the same time. If you gallop a horse, you make it gallop.","ex":{"en":"The horses galloped away","cn":"群马飞奔而去。"}},{"pos":"VERB 动词","cn":"骑马奔驰；策马飞奔","en":"If you gallop, you ride a horse that is galloping.","ex":{"en":"Major Winston galloped into the distance.","cn":"温斯顿少校策马疾驰而去。"}},{"pos":"N-SING 单数名词","cn":"骑马奔驰","en":"A gallop is a ride on a horse that is galloping.","ex":{"en":"I was forced to attempt a gallop.","cn":"我被迫试着骑马飞奔。"}},{"pos":"VERB 动词","cn":"飞速发展；高速增长","en":"If something such as a process gallops, it develops very quickly and is often difficult to control.","ex":{"en":"In spite of the recession, profits have galloped ahead.","cn":"尽管还处于萧条期，利润却迅猛增长。"}},{"pos":"VERB 动词","cn":"迅速奔跑；飞奔","en":"If you gallop, you run somewhere very quickly.","ex":{"en":"They are galloping around the garden playing football.","cn":"他们在园子里飞跑着踢足球。"}},{"pos":"PHRASE 短语","cn":"迅速地；飞快地","en":"If you do something at a gallop, you do it very quickly.","ex":{"en":"I read the book at a gallop.","cn":"我飞快地读完了这本书。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to run fairly slowly, taking short steps – used especially about horses and dogs","cn":""},{"en":"if a horse gallops, it runs very quickly","cn":""},{"en":"to suddenly run somewhere very fast, especially in order to escape","cn":""}]},"collocations":{"phrases":["ADJ. fast, good, head-down, mad | steady","VERB + GALLOP break into The horses broke into a mad gallop when they heard the gunshot.","PREP. at a ~ They reached the farm at a gallop. | into a ~ The noise startled the horse into a gallop. | ~ through (figurative) The programm","PHRASES at full gallop riders coming at full gallop"]},"media":{"uk":"media/ldoce/hwd/bre/f/gallop0703.mp3","us":"media/ldoce/hwd/ame/9/gallop1.mp3"},"examples":[{"en":"Jo galloped across the field towards him.","cn":"乔骑马穿过田野向他奔去。"},{"en":"My horse suddenly broke into a gallop.","cn":"我的马突然飞奔起来。"}],"oxford":{"phon":"ˈɡæləp","pos":"verb","senses":[{"en":"when a horse or similar animal gallops, it moves very fast and each stride includes a stage when all four feet are off the ground together","cn":"（马等）飞奔，奔驰，疾驰","g":"[intransitive]","ex":{"en":"The terrified horse galloped off.","cn":"那匹受惊的马飞奔而去。"}},{"en":"to ride a horse very fast, usually at a gallop","cn":"骑马奔驰；使（马）飞奔","g":"[intransitive, transitive]","ex":{"en":"Jo galloped across the field towards him.","cn":"乔骑马穿过田野向他奔去。"}},{"en":"to run very quickly","cn":"飞跑；奔跑","g":"[intransitive]","lab":"informal","ex":{"en":"She came galloping down the street.","cn":"她沿街飞奔而来。"}},{"en":"the fastest speed at which a horse can run, with a stage in which all four feet are off the ground together","cn":"（马的）飞奔，奔驰，疾驰","g":"[singular]","ex":{"en":"He rode off at a gallop.","cn":"他骑马疾驰而去。"},"pos":"noun"},{"en":"a ride on a horse at its fastest speed","cn":"骑马奔驰","g":"[countable]","ex":{"en":"to go for a gallop","cn":"去骑马奔驰一番"},"pos":"noun"},{"en":"an unusually fast speed; the act of doing something at an unusually fast speed","cn":"高速度；极快的动作","g":"[singular]","ex":{"en":"She always lives life at a gallop.","cn":"她一直过着快节奏的生活。"},"pos":"noun"}]}},"gamut":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"整个范围；全部","en":"The gamut of something is the complete range of things of that kind, or a wide variety of things of that kind.","ex":{"en":"Varied though the anthology may claim to be, it does not cover the whole gamut of Scottish poetry","cn":"该诗集虽然可能号称收录广泛，但并未涵盖所有苏格兰诗歌。"}},{"pos":"PHRASE 短语","cn":"涉及…的全部范围","en":"To run the gamut of something means to include, express, or experience all the different things of that kind, or a wide variety of them.","ex":{"en":"The show runs the gamut of 20th century design","cn":"展览涵盖20世纪的各种设计。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a set of many different things of the same general type that are available in the same place for the same use","cn":""},{"en":"a complete range of different types of things or people, especially when those at one end of the range are the opposite of those at the other end","cn":""},{"en":"a number of different things of the same kind that are available for you to choose or use","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A visit with a long-lost cousin might arouse emotions that run the gamut of joy, regret, sorrow, and excitement. A gamut is a full or complete range."}]},"collocations":{"phrases":["ADJ. complete, entire, full, whole","VERB + GAMUT cover, run (through)","PREP. ~ of The exhibition runs the whole gamut of artistic styles."]},"media":{"uk":"media/ldoce/hwd/bre/a/gamut0205.mp3","us":"media/ldoce/hwd/ame/0/gamut.mp3"},"examples":[{"en":"The network will provide the gamut of computer services to your home.","cn":"这个网络将为家庭提供全方位的计算机服务。"},{"en":"She felt she had run the (whole) gamut of human emotions from joy to despair.","cn":"她感到自己尝遍了从喜到悲的七情六欲。"}]},"gasp":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（尤指惊讶、震惊或疼痛时的）喘息，喘气，倒抽气","en":"A gasp is a short quick breath of air that you take in through your mouth, especially when you are surprised, shocked, or in pain.","ex":{"en":"An audible gasp went round the court as the jury announced the verdict","cn":"陪审团宣布判决的时候，听到法庭上有人倒抽了一口气。"}},{"pos":"VERB 动词","cn":"（尤指惊讶、震惊或疼痛时）喘息，喘气，倒抽气","en":"When you gasp, you take a short quick breath through your mouth, especially when you are surprised, shocked, or in pain.","ex":{"en":"She gasped for air and drew in a lungful of water","cn":"她喘了口气，吸入了一大口水。"}},{"pos":"PHRASE 短语","cn":"最终阶段；最后时刻","en":"You describe something as the last gasp to emphasize that it is the final part of something or happens at the last possible moment.","ex":{"en":"...the last gasp of a dying system of censorship","cn":"行将就木的审查制度的最终时刻"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to take air into your lungs and send it out again","cn":""},{"en":"to breathe out slowly and make a noise that shows you are disappointed, tired, relieved etc","cn":""},{"en":"to breathe quickly and noisily through your mouth, because you have been using a lot of effort","cn":""}]},"collocations":{"phrases":["ADJ. big, great | little, short, small | quick, sharp, sudden | loud | low | audible | shocked | strangled | involuntary","VERB + GASP give, let out | stifle | bring The stunt brought shocked gasps from the audience. | hear | take (in) taking in great gasps of ai","GASP + VERB escape sb","PREP. between ~s &lsquo;Listen carefully,&rsquo; he said, between gasps of breath. | in ~s He leant against the railing, his breath coming i"]},"media":{"uk":"media/ldoce/hwd/bre/c/gasp_v0205.mp3","us":"media/ldoce/hwd/ame/9/gasp1.mp3"},"examples":[{"en":"to give a gasp of horror/surprise/relief","cn":"惊恐得/吃惊得倒抽一口气；如释重负地松一口气"},{"en":"They gasped in astonishment at the news.","cn":"他们听到这消息惊讶得倒抽了一口气。"}],"oxford":{"phon":"ɡɑːsp","pos":"verb","senses":[{"en":"to take a quick deep breath with your mouth open, especially because you are surprised or in pain","cn":"（尤指由于惊讶或疼痛而）喘气，喘息，倒抽气","g":"[intransitive, transitive]","ex":{"en":"She gasped at the wonderful view.","cn":"如此美景使她惊讶得倒吸了一口气。"}},{"en":"to have difficulty breathing or speaking","cn":"透不过气；气喘吁吁地说","g":"[intransitive, transitive]","ex":{"en":"He came to the surface of the water gasping for air.","cn":"他浮出水面急促地喘着气。"}},{"en":"to want or need something very badly, especially a drink or a cigarette","cn":"渴望，很想要（尤指饮料或香烟）","g":"[intransitive]","lab":"British English, informal，，"},{"en":"a quick deep breath, usually caused by a strong emotion","cn":"（常指由强烈情感引起的）深吸气，喘息，倒抽气","ex":{"en":"to give a gasp of horror/surprise/relief","cn":"惊恐得／吃惊得倒抽一口气；如释重负地松一口气"},"pos":"noun"}]}},"gag":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（使人不能说话的）封口布，塞口物","en":"A gag is something such as a piece of cloth that is tied around or put inside someone's mouth in order to stop them from speaking.","ex":{"en":"His captors had put a gag of thick leather in his mouth.","cn":"劫持者用一块厚厚的皮革堵住了他的嘴。"}},{"pos":"VERB 动词","cn":"（用布）封住（或堵住）…的嘴","en":"If someone gags you, they tie a piece of cloth around your mouth in order to stop you from speaking or shouting.","ex":{"en":"I gagged him with a towel.","cn":"我用一条毛巾堵住他的嘴。"}},{"pos":"VERB 动词","cn":"压制…的言论自由；迫使…缄默","en":"If a person is gagged by someone in authority, they are prevented from expressing their opinion or from publishing certain information.","ex":{"en":"Judges must not be gagged.","cn":"法官的言论自由不能受到压制。"}},{"pos":"VERB 动词","cn":"噎住；噎得作呕","en":"If you gag, you cannot swallow and nearly vomit.","ex":{"en":"I knelt by the toilet and gagged.","cn":"我跪在马桶边，一阵恶心。"}},{"pos":"N-COUNT 可数名词","cn":"笑话；玩笑；插科打诨","en":"A gag is a joke.","ex":{"en":"...a gag about policemen giving evidence in court.","cn":"关于警察在法庭作证的一则笑话"}},{"pos":"VERB 动词","cn":"渴望拥有；期盼做","en":"If you say that someone is gagging for something or is gagging to do something, you are emphasizing that they want to have it or do it very much.","ex":{"en":"Girls everywhere are gagging for a car like this","cn":"天底下的女孩儿都对这种车梦寐以求。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"bring food or drink up from your stomach out through your mouth because you are ill, drunk, shocked etc","cn":""},{"en":"to bring food or drink up from your stomach out through your mouth - used especially in medical contexts","cn":""},{"en":"to bring food or drink up from your stomach out through your mouth because you are ill, drunk etc","cn":""}]},"collocations":{"phrases":["PHRASES bind and gag sb The men left the security guards bound and gagged."]},"media":{"uk":"media/ldoce/hwd/bre/d/gag_v0205.mp3","us":"media/ldoce/hwd/ame/b/gag1.mp3"},"examples":[{"en":"It was just a gag — we didn't mean to upset anyone.","cn":"这只是逗着玩，我们并未想使任何人不高兴。"},{"en":"The new laws are seen as an attempt to gag the press.","cn":"人们认为新法律企图压制新闻界的言论自由。"}],"oxford":{"phon":"ɡæɡ","pos":"noun","senses":[{"en":"a piece of cloth that is put over or in somebody’s mouth to stop them speaking","cn":"（使人不能说话的）封口布；塞口布","ex":{"en":"They tied him up and put a gag on him.","cn":"他们把他绑起来并用布堵住了他的嘴。"}},{"en":"an order that prevents something from being publicly reported or discussed","cn":"禁刊令（阻止公开报道或讨论某事的法令）","ex":{"en":"a press gag","cn":"新闻禁刊令"}},{"en":"a joke or a funny story, especially one told by a professional comedian","cn":"（尤指专业喜剧演员的）插科打诨，笑话，噱头","lab":"informal","ex":{"en":"to tell/crack a gag","cn":"讲笑话"}},{"en":"a trick you play on somebody","cn":"恶作剧；诡计；花招","lab":"especially North American English","ex":{"en":"It was just a gag—we didn't mean to upset anyone.","cn":"这只是逗着玩，我们没想让人不高兴。"}},{"en":"to put a piece of cloth in or over somebody’s mouth to prevent them from speaking or shouting","cn":"捂住，塞住（某人的嘴）","g":"[transitive]","ex":{"en":"The hostages were bound and gagged.","cn":"人质被绑起来并被人用东西塞住了嘴。"},"pos":"verb"},{"en":"to prevent somebody from speaking freely or expressing their opinion","cn":"压制…的言论自由；使缄默","g":"[transitive]","ex":{"en":"The new laws are seen as an attempt to gag the press.","cn":"人们认为新法律企图压制新闻界的言论自由。"},"pos":"verb"},{"en":"to have the unpleasant feeling in your mouth and stomach as if you are going to vomit","cn":"作呕","g":"[intransitive]","ex":{"en":"She gagged on the blood that filled her mouth.","cn":"她因嘴里充满了血而作呕。"},"pos":"verb"}]}},"gay":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"同性恋的","en":"A gay person is homosexual.","ex":{"en":"The quality of life for gay men has improved over the last two decades.","cn":"同性恋者的生活质量在过去20年里有了改善。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"快乐的；愉快的","en":"A gay person is fun to be with because they are lively and cheerful.","ex":{"en":"I am happy and free, in good health, gay and cheerful.","cn":"我快活自由，身体健康，积极乐观。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"鲜艳的；艳丽的","en":"A gay object is brightly coloured and pretty to look at.","ex":{"en":"I like gay, relaxing paintings.","cn":"我喜欢色彩鲜艳、让人放松的画。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"sexually attracted to people of the same sex","cn":""},{"en":"a woman who is sexually attracted to other women","cn":""},{"en":"sexually attracted to people of the same sex","cn":""}]},"vocab":{"pos":"n adj","senses":[{"en":"Gay is a word with many meanings. A gay person is homosexual, but if we describe something like a scene or a party as gay , that means it's bright, merry, and happy."}]},"collocations":{"phrases":["VERBS be, look, sound","ADV. openly He is now openly gay."]},"media":{"uk":"media/ldoce/hwd/bre/4/gay_adj0205.mp3","us":"media/ldoce/hwd/ame/1/gay1.mp3"},"examples":[{"en":"She didn't like the ringtone — said it was gay.","cn":"她不喜欢那个手机铃声，说它不时尚。"},{"en":"The garden was gay with red geraniums.","cn":"花园里红色的天竺葵花色彩艳丽。"}],"oxford":{"phon":"ɡeɪ","pos":"adjective","senses":[{"en":"sexually attracted to people of the same sex","cn":"同性恋的","ex":{"en":"gay men","cn":"同性恋的男人"}},{"en":"connected with people who are gay","cn":"与同性恋者有关的","g":"[only before noun]","ex":{"en":"a gay club/bar","cn":"同性恋者俱乐部／酒吧"}},{"en":"(used especially by young people) an offensive way to describe something you find boring, stupid or not attractive","cn":"（尤为年轻人用语）无聊，不时尚，没吸引力","g":"[not before noun]","lab":"slang, disapproving, offensive，，，，"},{"en":"happy and full of fun","cn":"愉快的；快乐的；充满乐趣的","lab":"old-fashioned","ex":{"en":"gay laughter","cn":"欢快的笑声"}},{"en":"brightly coloured","cn":"鲜艳的；艳丽的","lab":"old-fashioned","ex":{"en":"The garden was gay with red geraniums.","cn":"花园里红色的天竺葵花色彩艳丽。"}},{"en":"a person who is gay, especially a man","cn":"同性恋者（尤指男性）","pos":"noun"}]}},"gaol":{"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large building where people are kept as a punishment for a crime or while they are waiting to go to court for their trial","cn":""},{"en":"a prison, or a similar smaller building where prisoners are kept for a short time","cn":""},{"en":"another way of spelling jail","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41gaol.mp3","us":"media/ldoce/hwd/ame/b/ld41gaol.mp3"},"oxford":{"phon":"dʒeɪl","pos":"noun","senses":[{"en":"jail (= a prison)","cn":"监狱"},{"en":"jail (= to put somebody in prison)","cn":"监狱","pos":"verb"}]}},"galaxy":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"星系","en":"A galaxy is an extremely large group of stars and planets that extends over many billions of light years.","ex":{"en":"Astronomers have discovered a distant galaxy.","cn":"天文学家们发现了一个遥远的星系。"}},{"pos":"N-PROPER 专有名词","cn":"银河；银河系","en":"The Galaxy is the extremely large group of stars and planets to which the Earth and the Solar System belong.","ex":{"en":"The Galaxy consists of 100 billion stars.","cn":"银河系由1,000亿颗恒星组成。"}},{"pos":"N-SING 单数名词","cn":"一群（名人）；（人才）荟萃","en":"If you talk about a galaxy of people from a particular profession, you mean a group of them who are all famous or important.","ex":{"en":"He is one of a small galaxy of Dutch stars on German television.","cn":"出现在德国电视上的荷兰明星为数不多，他是其中一位。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large ball of burning gas in space, which can be seen at night as a point of light in the sky","cn":""},{"en":"one of the large objects that goes around the Sun, for example the Earth, Saturn, Mercury, or Mars","cn":""},{"en":"the star that gives us light and heat, around which the planets move. There are also many millions of other suns in the universe","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"A galaxy is a collection of stars and planets that are held together by gravity. In a galaxy , the celestial bodies rotate around a central object."}]},"collocations":{"phrases":["ADJ. distant | nearby, nearest, neighbouring","PREP. in a/the ~ scientists observing phenomena in nearby galaxies"]},"media":{"uk":"media/ldoce/hwd/bre/4/galaxy0205.mp3","us":"media/ldoce/hwd/ame/6/galaxy.mp3"},"examples":[{"en":"a galaxy of Hollywood stars","cn":"好莱坞影星的荟萃"},{"en":"a galaxy of British artistic talent","cn":"灿若星汉的英国艺术人才"}],"oxford":{"phon":"ˈɡæləksi","pos":"noun","senses":[{"en":"any of the large systems of stars, etc. in outer space","cn":"星系","g":"[countable]","ex":{"en":"scientists observing phenomena in nearby galaxies","cn":"观察邻近星系现象的科学家"}},{"en":"the system of stars that contains our sun and its planets, seen as a band of light in the night sky","cn":"银河；银河系","g":"[singular]"},{"en":"a group of famous people, or people with a particular skill","cn":"群英；人才荟萃","g":"[countable]","lab":"informal","ex":{"en":"a galaxy of Hollywood stars","cn":"好莱坞影星的荟萃"}},{"en":"a popular make of chocolate bar in Britain, sold as Dove in the US and other countries","cn":"在英国流行的巧克力棒品牌，在美国和其他国家/地区以Dove的形式出售"}]}},"gape":{"collins":{"senses":[{"pos":"VERB 动词","cn":"目瞪口呆地凝视；张口结舌地看","en":"If you gape, you look at someone or something in surprise, usually with an open mouth.","ex":{"en":"His secretary stopped taking notes to gape at me","cn":"他的秘书停止了记录，目瞪口呆地望着我。"}},{"pos":"VERB 动词","cn":"（洞、伤口等）张开，裂开","en":"If you say that something such as a hole or a wound gapes, you are emphasizing that it is big or wide.","ex":{"en":"The front door was missing. A hole gaped in the roof.","cn":"前门不翼而飞，屋顶豁开了一个洞。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to turn your eyes towards someone or something, so that you can see them","cn":""},{"en":"to look at something quickly, especially in order to find or check something","cn":""},{"en":"to look at someone or something for a short time and then look quickly away","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"If Bigfoot walked down your street wearing a tutu, you might gape or stare at the man-ape with your mouth open. You'd really gape if the tutu had a gaping, or wide open, hole."}]},"collocations":{"phrases":["PREP. at What are you gaping at?","PHRASES gape open She watched him, her mouth gaping open. (figurative) The empty cash box lay gaping open in one corner."]},"media":{"uk":"media/ldoce/hwd/bre/4/gape0205.mp3","us":"media/ldoce/hwd/ame/5/gape.mp3"},"examples":[{"en":"He stood yawning, his pyjama jacket gaping open.","cn":"他敞开睡衣站着打哈欠。"},{"en":"a gaping hole/mouth/wound","cn":"豁开的洞；张大的嘴；裂开的伤口"}],"oxford":{"phon":"ɡeɪp","pos":"noun","senses":[{"en":"an act of staring at somebody/something with your mouth open because you are shocked or surprised","cn":"目瞪口呆","ex":{"en":"She climbed into her sports car to the gapes of passers-by.","cn":"行人目瞪口呆地看着她爬进她的跑车里。"}},{"en":"a large wide open mouth or beak","cn":"大张着的嘴（或喙）","ex":{"en":"The perch has the large eye and wide gape of an active hunter.","cn":"鲈鱼有着大眼睛和张大的嘴巴，就像活跃的猎人一样。"}},{"en":"to stare at somebody/something with your mouth open because you are shocked or surprised","cn":"张口结舌地看；目瞪口呆地凝视","g":"[intransitive]","ex":{"en":"Isabel gaped at him, horrified.","cn":"伊莎贝尔惊恐地目瞪口呆地看着他。"},"pos":"verb"},{"en":"to be or become wide open","cn":"张开；裂开；豁开","g":"[intransitive]","ex":{"en":"a gaping hole/mouth/wound","cn":"豁开的洞；张大的嘴；裂开的伤口"},"pos":"verb"}]}},"gale":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"大风；强风","en":"A gale is a very strong wind.","ex":{"en":"...forecasts of fierce gales over the next few days.","cn":"预报未来几天有超强大风"}},{"pos":"N-COUNT 可数名词","cn":"一阵（大笑声）","en":"You can refer to the loud noise made by a lot of people all laughing at the same time as a gale of laughter or gales of laughter.","ex":{"en":"This was greeted with gales of laughter from the audience.","cn":"观众对此报以阵阵笑声。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a very strong wind","cn":"大风"},{"en":"a storm that has very strong fast winds and that moves over water – used about storms in the North Atlantic Ocean","cn":""},{"en":"a violent tropical storm – used about storms in the Western Pacific Ocean","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"If there’s a gale coming your way, you better hold onto your new hat and your little dog, Toto, too, because this is an extremely strong wind."}]},"collocations":{"phrases":["ADJ. fierce, full, great, heavy, howling, severe, strong | Force 9, Force 10, etc. | northerly, westerly, etc. | autumn, winter, etc. | equi","VERB + GALE blow It was blowing a gale outside. | get caught in We got caught in a howling gale.","GALE + VERB blow A severe gale was blowing along the coast.","GALE + NOUN force gale force winds | warning","PREP. in ~ The tree had come down in a fierce gale the night before."]},"media":{"uk":"media/ldoce/hwd/bre/e/gale0205.mp3","us":"media/ldoce/hwd/ame/f/gale.mp3"},"examples":[{"en":"His speech was greeted with gales of laughter.","cn":"人们对他的演讲报以阵阵笑声。"},{"en":"The gale blew down hundreds of trees.","cn":"大风吹倒了数百棵树。"}],"oxford":{"phon":"ɡeɪl","pos":"noun","senses":[{"en":"an extremely strong wind","cn":"大风；8 级风","lab":"British English","ex":{"en":"The gale blew down hundreds of trees.","cn":"大风吹倒了数百棵树。"}}]}},"gala":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"庆典；演出；盛会","en":"A gala is a special public celebration, entertainment, performance, or festival.","ex":{"en":"...a gala evening at the Royal Opera House.","cn":"在皇家歌剧院举行的盛大晚会"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a public entertainment or performance to celebrate a special occasion","cn":"庆典﹐演出盛会"},{"en":"a sports competition, especially in swimming","cn":"运动会〔尤指游泳比赛〕"}]},"vocab":{"pos":"n","senses":[{"en":"A gala is a big party. If you're going to a gala, you'll want to wear your fanciest ball gown — you'll want to look great for the best party of the year."}]},"collocations":{"phrases":["ADJ. charity, Royal | swimming","VERB + GALA have, hold | attend, go to","GALA + NOUN concert, day, dinner, evening, event, night, occasion, performance, weekend"]},"media":{"uk":"media/ldoce/hwd/bre/d/gala0205.mp3","us":"media/ldoce/hwd/ame/9/gala.mp3"},"examples":[{"en":"a gala dinner/night","cn":"盛宴；晚会"},{"en":"a charity gala","cn":"慈善义演"}],"oxford":{"phon":"ˈɡɑːlə","pos":"noun","senses":[{"en":"a special public celebration or entertainment","cn":"庆典；盛会；演出","ex":{"en":"a charity gala","cn":"慈善义演"}},{"en":"a sports competition, especially in swimming","cn":"体育运动会，体育竞赛（尤指游泳）","lab":"British English","ex":{"en":"a swimming gala","cn":"游泳比赛"}}]}},"gadget":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"小器具；精巧的小玩意","en":"A gadget is a small machine or device which does something useful. You sometimes refer to something as a gadget when you are suggesting that it is complicated and unnecessary.","ex":{"en":"...kitchen gadgets including toasters, kettles and percolators.","cn":"烤面包机、水壶、滴滤式咖啡壶等厨用小家电"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of equipment with moving parts that uses power such as electricity to do a particular job","cn":""},{"en":"a machine or piece of electrical equipment, usually a large one, that people use in the home","cn":""},{"en":"a piece of equipment, usually a small electronic one, that does a special job","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A gadget is a tool or device, especially one that works remarkably well for a specific task. Your dad's favorite kitchen gadget might be his special knife that cuts vegetables into spirals."}]},"collocations":{"phrases":["ADJ. little | clever, neat, nifty | useless | latest, modern, new | electrical, electronic | kitchen","VERB + GADGET invent","PREP. ~ for She has invented a nifty little gadget for undoing stubborn nuts and bolts."]},"media":{"uk":"media/ldoce/hwd/bre/8/gadget0205.mp3","us":"media/ldoce/hwd/ame/d/gadget.mp3"},"examples":[{"en":"a neat gadget for sharpening knives","cn":"精巧的磨刀工具"}],"oxford":{"phon":"ˈɡædʒɪt","pos":"noun","senses":[{"en":"a small tool or device that does something useful","cn":"小器具；小装置","ex":{"en":"We live in a world filled with high-tech gadgets.","cn":"我们生活的世界满是高科技小器具。"}}]}},"garlic":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"蒜；大蒜","en":"Garlic is the small, white, round bulb of a plant that is related to the onion plant. Garlic has a very strong smell and taste and is used in cooking.","ex":{"en":"...a clove of garlic.","cn":"一瓣蒜"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a plant like a small onion, used in cooking to give a strong taste （","cn":"大）蒜"}]},"collocations":{"phrases":["ADJ. wild","QUANT. clove","VERB + GARLIC peel | chop, crush","GARLIC + NOUN clove | bread | sausage •"]},"media":{"img":["media/ldoce/img/garlic.jpg","media/thumb/garlic.jpg"],"uk":"media/ldoce/hwd/bre/4/garlic0205.mp3","us":"media/ldoce/hwd/ame/4/garlic.mp3"},"examples":[{"en":"a clove of garlic (= one section of it)","cn":"一瓣蒜"},{"en":"garlicky breath/food","cn":"带大蒜味的气息；加有大蒜的食物"}],"oxford":{"phon":"ˈɡɑːlɪk","pos":"noun","senses":[{"en":"a vegetable of the onion family with a very strong taste and smell, used in cooking to add taste to food","cn":"蒜；大蒜","ex":{"en":"a clove of garlic (= one section of it)","cn":"一瓣蒜"}}]}},"garment":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（一件）衣服（尤用于谈及服装的制作和销售时）","en":"A garment is a piece of clothing; used especially in contexts where you are talking about the manufacture or sale of clothes. →see usage note at:","ex":{"en":"Many of the garments have the customers' name tags sewn into the linings.","cn":"这些衣服有很多内衬上缝有顾客的姓名签。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"things that you wear, for example coats, shirts, and dresses","cn":""},{"en":"clothes in general - use this either to talk about a particular type of clothes, or to talk about a large quantity of clothes","cn":""},{"en":"clothes, especially clothes for a particular event or occasion","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A garment is a piece of clothing. The area of New York City where clothes are manufactured is known as the Garment District."}]},"collocations":{"phrases":["ADJ. heavy | shapeless | knitted, woollen","VERB + GARMENT have on, wear She wore a shapeless knitted garment."]},"media":{"uk":"media/ldoce/hwd/bre/5/garment0205.mp3","us":"media/ldoce/hwd/ame/3/garment.mp3"},"examples":[{"en":"a strange shapeless garment that had once been a jacket","cn":"用夹克衫改成的不成形的一件怪衣服"},{"en":"woollen/winter/outer garments","cn":"毛衣；冬装；外衣"}],"oxford":{"phon":"ˈɡɑːmənt","pos":"noun","senses":[{"en":"a piece of clothing","cn":"（一件）衣服","ex":{"en":"a strange shapeless garment that had once been a jacket","cn":"用夹克衫改成的不成形的一件怪衣服"}}]}},"gamble":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"冒险；投机；赌博","en":"A gamble is a risky action or decision that you take in the hope of gaining money, success, or an advantage over other people.","ex":{"en":"Yesterday, he named his cabinet and took a big gamble in the process.","cn":"昨天他冒了很大的风险任命了内阁成员。"}},{"pos":"VERB 动词","cn":"冒险；碰运气；以…为赌注","en":"If you gamble on something, you take a risky action or decision in the hope of gaining money, success, or an advantage over other people.","ex":{"en":"Few firms will be willing to gamble on new products","cn":"很少有公司愿意冒险开发新产品。"}},{"pos":"VERB 动词","cn":"（在纸牌、赛马等中）赌（钱）；赌博","en":"If you gamble an amount of money, you bet it in a game such as cards or on the result of a race or competition. People who gamble usually do it frequently.","ex":{"en":"Most people visit Las Vegas to gamble their hard-earned money","cn":"大多数人拿着辛苦挣来的钱去拉斯维加斯赌博。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to try to win money, for example by playing cards or guessing which horse will win a race","cn":""},{"en":"to try to win money by guessing who will win a race or game","cn":""},{"en":"to gamble £10, $20 etc on the horse or team that you think will win a race or competition","cn":""}]},"collocations":{"phrases":["ADJ. big, huge, major | calculated | desperate It was time for a last desperate gamble. | political","VERB + GAMBLE take","GAMBLE + VERB pay off, work I took a calculated gamble and it paid off.","PREP. ~ on Backpackers with a heavy load should resist taking a gamble on the weather.","PHRASES a bit/something of a gamble Trying to find the right pension can be a bit of a gamble."]},"media":{"uk":"media/ldoce/hwd/bre/e/gamble_v0205.mp3","us":"media/ldoce/hwd/ame/1/gamble1.mp3"},"examples":[{"en":"They invested money in the company right at the start and the gamble paid off (= brought them success).","cn":"他们一开始就把资金投到这家公司，结果这一冒险获得了成功。"},{"en":"She knew she was taking a gamble but decided it was worth it.","cn":"她知道是在冒险，但她认为冒这个险值得。"}],"oxford":{"phon":"ˈɡæmbl","pos":"verb","senses":[{"en":"to risk money on a card game, horse race, etc.","cn":"（牌戏、赛马等中）赌博，打赌","g":"[intransitive, transitive]","ex":{"en":"to gamble at cards","cn":"赌纸牌"}},{"en":"to risk losing something in the hope of being successful","cn":"冒风险；碰运气；以…为赌注","g":"[transitive, intransitive]","ex":{"en":"He's gambling his reputation on this deal.","cn":"他在以自己的声誉为这笔交易作赌注。"}},{"en":"an action that you take when you know there is a risk but when you hope that the result will be a success","cn":"赌博；打赌；冒险","ex":{"en":"She knew she was taking a gamble but decided it was worth it.","cn":"她知道是在冒险，但她认为冒这个险值得。"},"pos":"noun"}]}}});
